using System;using System.Data;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class SavedJobsPage:UserControl{DataGridView grid;Label info;public SavedJobsPage(){Dock=DockStyle.Fill;BackColor=Theme.Background;Padding=new Padding(18);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=56,FlowDirection=L.Fa?FlowDirection.RightToLeft:FlowDirection.LeftToRight};var save=Ui.Button(L.Fa?"ذخیره فرصت انتخاب‌شده":"Save selected job");var remove=Ui.Button(L.Fa?"حذف از ذخیره‌ها":"Remove saved",false);var refresh=Ui.Button(L.Fa?"تازه‌سازی":"Refresh",false);save.Click+=delegate{Toggle(true);};remove.Click+=delegate{Toggle(false);};refresh.Click+=delegate{LoadData();};bar.Controls.Add(save);bar.Controls.Add(remove);bar.Controls.Add(refresh);info=Ui.Label("",9);info.ForeColor=Theme.Muted;info.Dock=DockStyle.Bottom;info.Height=34;grid=Ui.Grid();Controls.Add(grid);Controls.Add(info);Controls.Add(bar);LoadData();}void LoadData(){grid.DataSource=Database.Query(@"SELECT j.Id,j.Title,ISNULL(c.Name,'') Company,j.City,j.EmploymentType,CASE WHEN f.Id IS NULL THEN N'☆' ELSE N'★' END Saved,j.Status FROM Jobs j LEFT JOIN Companies c ON c.Id=j.CompanyId LEFT JOIN Favorites f ON f.EntityType='Job' AND f.EntityId=j.Id AND f.UserId=@u WHERE j.Status='Open' ORDER BY CASE WHEN f.Id IS NULL THEN 1 ELSE 0 END,j.CreatedAt DESC",new SqlParameter("@u",AppSession.UserId));info.Text=L.Fa?"★ یعنی این فرصت در فهرست ذخیره‌های شماست.":"★ means this job is saved to your shortlist.";}int SelectedId(){if(grid.CurrentRow==null)return 0;return Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);}void Toggle(bool add){int id=SelectedId();if(id==0)return;if(add)Database.Exec("IF NOT EXISTS(SELECT 1 FROM Favorites WHERE UserId=@u AND EntityType='Job' AND EntityId=@i) INSERT Favorites(UserId,EntityType,EntityId) VALUES(@u,'Job',@i)",new SqlParameter("@u",AppSession.UserId),new SqlParameter("@i",id));else Database.Exec("DELETE Favorites WHERE UserId=@u AND EntityType='Job' AND EntityId=@i",new SqlParameter("@u",AppSession.UserId),new SqlParameter("@i",id));Database.Audit(add?"SaveJob":"UnsaveJob","Job",id.ToString());LoadData();}}}
